#include <iostream>
#include <vector>
#include <cmath>
#include <cassert>
#include <cstring>

using namespace std;

const long long MOD = 1000000007;

struct Matrix {
    int size;
    long long mat[33][33];

    Matrix(int n = 0, long long val = 0) : size(n) {
        memset(mat, 0, sizeof(mat));
        for (int i = 0; i < n; ++i) {
            mat[i][i] = val;
        }
    }

    Matrix multiply(const Matrix& other) const {
        assert(size == other.size);
        Matrix result(size);
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j) {
                for (int k = 0; k < size; ++k) {
                    result.mat[i][k] = (result.mat[i][k] + mat[i][j] * other.mat[j][k]) % MOD;
                }
            }
        }
        return result;
    }

    Matrix& multiplyAssign(const Matrix& other) {
        *this = multiply(other);
        return *this;
    }

    Matrix power(int e) const {
        Matrix res(size, 1);
        Matrix base = *this;
        int exp = e;
        while (exp > 0) {
            if (exp & 1) res.multiplyAssign(base);
            base = base.multiply(base);
            exp >>= 1;
        }
        return res;
    }
};

int main() {
    long long n;
    int k;
    cin >> n >> k;
    if (n <= k) {
        cout << (1LL << n) % MOD << "\n";
        return 0;
    }

    int logN = int(log(n + 0.0) / log(k + 0.0)) + 2;

    Matrix shift(k + 1, 1);
    for (int j = 0; j < k; ++j) {
        shift.mat[j][j] = 0;
        shift.mat[(j + 1) % k][j] = 1;
    }

    vector<Matrix> block(logN);
    block[0] = Matrix(k + 1, 1);
    for (int i = 1; i <= k; ++i) {
        block[0].mat[0][i] = 1;
    }

    for (int i = 1; i < logN; ++i) {
        block[i] = (block[i - 1].multiply(shift)).power(k);
    }

    int idx = 0;
    long long len = 1;
    while (n / len >= k) {
        ++idx;
        len *= k;
    }

    Matrix m(k + 1, 1);
    long long rem = n;
    long long currentLen = len;
    int i = idx;

    while (rem > 0) {
        if (currentLen <= rem) {
            int x = int(rem / currentLen);
            m.multiplyAssign((block[i] * shift).power(x));
            rem -= currentLen * x;
        }
        --i;
        currentLen /= k;
    }

    long long answer = 0;
    for (int i = 0; i <= k; ++i) {
        answer = (answer + m.mat[i][k]) % MOD;
    }
    cout << answer << "\n";

    return 0;
}
